#!/usr/bin/env node

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { createHmac, createPrivateKey, createPublicKey, sign as cryptoSign, timingSafeEqual, verify as cryptoVerify } from "node:crypto";
import {
  HLCWidGen,
  parseHlcWid,
  parseWid,
  validateHlcWid,
  validateWid,
  WidGen,
} from "./index";
import { parseTimeUnit, type TimeUnit } from "./time";

/** CLI mode selector for WID vs HLC workflows. */
type Kind = "wid" | "hlc";

/** Parsed CLI options that drive each command. */
interface Opts {
  /** Operation kind (wid or hlc). */
  kind: Kind;
  node: string;
  W: number;
  Z: number;
  timeUnit: TimeUnit;
  count: number;
  json: boolean;
}

/** Canonical mode parameters sent on CLI helpers. */
interface Canon {
  A: string;
  W: number;
  L: number;
  D: string;
  I: string;
  E: string;
  Z: number;
  T: TimeUnit;
  R: string;
  M: boolean;
  N: number;
  /**
   * True only for a real L=<n> (not omitted, not the L=# placeholder).
   * A=stream treats an unset L as 0 (no sleep); the 3600 default applies
   * to the Rust-only service loops, not streaming.
   */
  LExplicit: boolean;
  WID?: string;
  KEY?: string;
  SIG?: string;
  DATA?: string;
  OUT?: string;
  MODE?: string;
  CODE?: string;
  DIGITS?: number;
  MAX_AGE_SEC?: number;
  MAX_FUTURE_SEC?: number;
}

